const b = $input.first().json.body || $input.first().json || {};
const topk = Math.max(1, Math.min(10, parseInt(b.top_k) || 4));
const gids = (function(v){ if (v === undefined || v === null || v === '') return []; const a = Array.isArray(v) ? v : [v]; return a.map(function(x){ return parseInt(x); }).filter(function(x){ return x > 0; }); })(b.group_ids !== undefined ? b.group_ids : b.group_id);
return [{ json: { question: (b.question || '').toString().slice(0, 2000),
  group_id: gids.length ? gids[0] : null,
  group_ids: gids,
  session_id: (b.session_id || 'web-' + Date.now()).toString(), top_k: topk } }];

const p = $('Prep').first().json;
const e = $input.first().json;
if (!e.embedding || !e.embedding.values) throw new Error('embed ล้มเหลว');
const vec = '[' + e.embedding.values.map(v => Number(v).toFixed(8)).join(',') + ']';
const gids = Array.isArray(p.group_ids) ? p.group_ids.map(function(x){ return parseInt(x); }).filter(function(x){ return x > 0; }) : [];
const gid = gids.length ? gids : ((p.group_id === null || p.group_id === undefined) ? null : [parseInt(p.group_id)]);
const topk = Math.max(1, Math.min(10, parseInt(p.top_k) || 4));
const where = (!gid || !gid.length) ? '' : ` AND (c.metadata->>'group_id')::int IN (${gid.join(',')})`;
const sql = `SELECT c.content, c.metadata, 1 - (c.embedding <=> '${vec}'::vector) AS sim FROM rag_chunks c WHERE 1=1${where} ORDER BY c.embedding <=> '${vec}'::vector LIMIT ${topk}`;
return [{ json: { ...p, embedding: e.embedding, sql: sql } }];

const items = $input.all().map(r => r.json);
const rows = items.filter(r => r.content !== undefined);
const rel = items.filter(r => r.name !== undefined);
const pre = $('Attach Params').first().json;
const ctx = rows.map((r, i) => `[${i + 1}] (group=${(r.metadata||{}).group_name||''}, src=${(r.metadata||{}).title||''}, sim=${Number(r.sim||0).toFixed(3)})\n${r.content}${(r.metadata||{}).image_url ? '\n[image: ' + r.metadata.image_url + ']' : ''}`).join('\n\n');
const relTxt = 'groups: ' + rel.map(r => r.name + '(' + r.chunks + ')').join(', ');
return [{ json: { question: pre.question || '', session_id: pre.session_id || '', context: ctx, rel: relTxt } }];

const b = $('Build Prompt').first().json;
let sid = (b.session_id || '').toString();
if (!/^[A-Za-z0-9:_-]{1,128}$/.test(sid)) sid = 'web-default';
const q = (s) => s.replace(/'/g, "''");
return [{ json: { sql: `SELECT COALESCE((SELECT json_agg(message ORDER BY id DESC) FROM (SELECT message, id FROM n8n_chat_histories WHERE session_id = '${q(sid)}' ORDER BY id DESC LIMIT 10) t), '[]'::json) AS history` } }];

const b = $('Build Prompt').first().json;
let hist = [];
try { const h = $('Read Mem History').first().json.history; hist = Array.isArray(h) ? h.slice().reverse() : []; } catch(e) { hist = []; }
const hlines = hist.filter(m => m && (m.content || '').toString().trim()).slice(-10).map(m => ((m.type === 'ai' ? 'บอท: ' : 'ผู้ใช้: ') + (m.content || '').toString().trim().slice(0, 400)));
const hblock = hlines.length ? ('

ประวัติการสนทนาก่อนหน้า:
' + hlines.join('
')) : '';
const content = 'คำถาม: ' + (b.question || '') + hblock + '

<context>
' + (b.context || '') + '
</context>

ข้อมูลเสริม(relational): ' + (b.rel || '') + '

ตอบตามกติกาด้านบนเป็นภาษาไทย (ใช้ประวัติประกอบเมื่อคำถามอ้างถึงเรื่องก่อนหน้า)';
return [{ json: { system: "You are the knowledge assistant of TripThai/ChatDesk (Thai hotel & org QA).
STRICT RULES:
1) Answer ONLY from the provided <context>. Reply in Thai, concise (2-5 sentences for chat).
2) If the context has nothing relevant, say exactly: "ไม่พบข้อมูลนี้ในฐานความรู้ กรุณาติดต่อเจ้าหน้าที่ค่ะ" — never invent prices, policies, dates, names or contacts.
3) Never hallucinate numbers. Quote exactly as in context.
4) IMAGES: context rows may include [image: URL]. When the user asks to see a picture AND a row has one, mention it briefly; put each URL on its own line verbatim (raw URL only) so the UI can render it.
5) Cite the source group/title briefly when useful.
6) Conversation history is ONLY for resolving what the question refers to (pronouns and follow-ups). NEVER copy facts, numbers, policies, laws or specs from history. Facts must come from the <context> section only, even if history says otherwise.", messages: [{ role: 'user', content: content }] } }];

const it = $input.first().json;
let t = '';
try { t = ((it.message || {}).content || '').toString(); } catch(e) {}
t = t.replace(/^[\s\S]*?<\/think>/, '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
if (!t) throw new Error('Local LLM ไม่ตอบ');
return [{ json: { output: t.slice(0, 2000) } }];

const a = $input.first().json;
const b = $('Build Prompt').first().json;
let sid = (b.session_id || '').toString();
if (!/^[A-Za-z0-9:_-]{1,128}$/.test(sid)) sid = 'web-default';
const q = (s) => (s || '').toString().replace(/'/g, "''");
const hq = (b.question || '').toString().slice(0, 2000);
const an = ((a.output || '').toString()).slice(0, 2000);
const hj = JSON.stringify({ type: 'human', content: hq });
const aj = JSON.stringify({ type: 'ai', content: an });
const sql = `WITH ins AS (INSERT INTO n8n_chat_histories (session_id, message) VALUES ('${q(sid)}', '${q(hj)}'::jsonb), ('${q(sid)}', '${q(aj)}'::jsonb) RETURNING id), del AS (DELETE FROM n8n_chat_histories WHERE session_id = '${q(sid)}' AND id NOT IN (SELECT id FROM n8n_chat_histories WHERE session_id = '${q(sid)}' ORDER BY id DESC LIMIT 60) RETURNING 1) SELECT (SELECT COUNT(*) FROM ins) AS saved, (SELECT COUNT(*) FROM del) AS pruned`;
return [{ json: { sql: sql } }];

